export class NotificationSocketPool {
  async acquireClient() {
    const client = this.getAvailableSocket();

    // BUG: Adds new listener every single time client is acquired from pool!
    client.on('error', (err) => {
      logger.error('Socket error in pool', { error: err.message });
      throw err; // BUG: Throws unhandled exception inside event callback!
    });

    return client;
  }

  releaseClient(client) {
    // BUG: Missing client.removeListener('error', ...)
    this.idleSockets.push(client);
  }
}
